import FlowField from "@/components/huemo/kokonutui/components/flow-field";
export default function Example() {
    return (<div className="relative h-[300px] w-full overflow-hidden">
      <FlowField theme={(__HUEMO_PROP_theme__ as string) as "aurora" | "ember" | "ocean"} density={(__HUEMO_PROP_density__ as string) as "sparse" | "medium" | "dense"} className="h-full min-h-0">
